<template>
  <div slot="header">
    <div id="Industry" :style="{width: '100%', height: '500px'}"></div>
    <div class="title font-weight-midle mb-2 text-xs-center black--text">说明</div>
    <div class="font-weight-thin text-xs-center grey--text" >
      <span class="font-weight-bold">注</span>：只保留出现次数大于2次的标签；<br>
      <span class="font-weight-bold">使用提示</span>：左键可拖拽，点击和滚轮可缩放。
    </div>
  </div>
</template>

<script>
const axios = require('axios');
export default {
  data: () => ({
  }),
  mounted() {
    this.drawGraph();
  },
  methods: {
    drawGraph(){
        // 基于准备好的dom，初始化echarts实例
        let myChart = this.$echarts.init(document.getElementById('Industry'));

        axios.get('./data/company_industry.json?v=1').then((response) => {
          let dataAxis = response.data.name;
          let data = response.data.value;
          let yMax = 0;
          let dataShadow = [];

          for (var i = 0; i < data.length; i++) {
              dataShadow.push(yMax);
          }

          let option = {
            title: {
                text: '行业分布',
                subtext: '有数据分析相关职位公司的行业分布',
                left: 'center'
            },
            xAxis: {
                data: dataAxis,
                axisLabel: {
                    inside: true,
                    textStyle: {
                        color: '#333'
                    },
                    rotate: 90,
                },
                axisTick: {
                    show: false
                },
                axisLine: {
                    show: false
                },
                z: 10
            },
            yAxis: {
                axisLine: {
                    show: false
                },
                axisTick: {
                    show: false
                },
                axisLabel: {
                    textStyle: {
                        color: '#999'
                    }
                }
            },
            dataZoom: [
                {
                    type: 'inside'
                }
            ],
            series: [
                { // For shadow
                    type: 'bar',
                    itemStyle: {
                        normal: {color: 'rgba(0,0,0,0.05)'}
                    },
                    barGap:'-100%',
                    barCategoryGap:'40%',
                    data: dataShadow,
                    animation: false
                },
                {
                    type: 'bar',
                    itemStyle: {
                        normal: {
                            color: new this.$echarts.graphic.LinearGradient(
                                0, 0, 0, 1,
                                [
                                    {offset: 0, color: '#83bff6'},
                                    {offset: 0.5, color: '#188df0'},
                                    {offset: 1, color: '#188df0'}
                                ]
                            )
                        },
                        emphasis: {
                            color: new this.$echarts.graphic.LinearGradient(
                                0, 0, 0, 1,
                                [
                                    {offset: 0, color: '#2378f7'},
                                    {offset: 0.7, color: '#2378f7'},
                                    {offset: 1, color: '#83bff6'}
                                ]
                            )
                        }
                    },
                    data: data
                }
            ]
        };

        // Enable data zoom when user click bar.
        var zoomSize = 6;
        myChart.on('click', function (params) {
            console.log(dataAxis[Math.max(params.dataIndex - zoomSize / 2, 0)]);
            myChart.dispatchAction({
                type: 'dataZoom',
                startValue: dataAxis[Math.max(params.dataIndex - zoomSize / 2, 0)],
                endValue: dataAxis[Math.min(params.dataIndex + zoomSize / 2, data.length - 1)]
            });
        });
        // 绘制图表
        myChart.setOption(option);
      });
    },
  }
}
</script>
